const fmt=(v,n=2)=>Number(v.toFixed(n)).toString(),rad=n=>n*Math.PI/180;
export function elbowFabricationSVG(e,od){
  if(!e||e.kind!=='cut')return '';
  const radius=e.radius,half=od/2,donor=rad(e.donor),angle=e.theta,tangent=e.tangent??0;
  const scale=Math.min(315/Math.max((radius+half)*Math.sin(donor)+tangent,1),160/Math.max(radius+half,1));
  const origin=[65+tangent*scale,220],at=(rho,b)=>[origin[0]+rho*Math.sin(b)*scale,origin[1]-(radius-rho*Math.cos(b))*scale];
  const xy=p=>p.map(v=>fmt(v)).join(','),arc=(rho,t)=>Array.from({length:49},(_,i)=>(i?'L':'M')+xy(at(rho,t*i/48))).join(' ');
  const inner=at(radius-half,angle),outer=at(radius+half,angle),innerStart=at(radius-half,0),outerStart=at(radius+half,0);
  const circle=[565,151],cr=59;
  const marks=e.stations.slice(0,-1).map(s=>{const t=rad(s.clock),x=circle[0]+cr*Math.sin(t),y=circle[1]-cr*Math.cos(t);return `<circle cx="${fmt(x)}" cy="${fmt(y)}" r="2.5"/>`;}).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 740 325" role="img" aria-label="${e.end} 彎頭加工：保留 ${fmt(e.angle,4)} 度，外背沿弧 ${fmt(e.outerArc)}，內腹沿弧 ${fmt(e.innerArc)} 毫米"><g font-family="Arial,Microsoft JhengHei" fill="#162c43"><text x="18" y="23" font-size="17" font-weight="bold">${e.end} 彎頭 · 原 ${fmt(e.donor)}° → 保留 ${fmt(e.angle,4)}°</text><text x="18" y="44" font-size="12">側面示意（非等比例）· Rc ${fmt(radius)} · OD ${fmt(od)} mm</text></g><g fill="none" stroke-linecap="round"><path d="${arc(radius+half,donor)}" stroke="#b9c1ca" stroke-width="5"/><path d="${arc(radius-half,donor)}" stroke="#b9c1ca" stroke-width="5"/><path d="${arc(radius,donor)}" stroke="#b9c1ca" stroke-dasharray="4 4"/><path d="${arc(radius+half,angle)}" stroke="#1675ad" stroke-width="5"/><path d="${arc(radius-half,angle)}" stroke="#1675ad" stroke-width="5"/><path d="M${xy(inner)}L${xy(outer)}" stroke="#c4771b" stroke-width="3"/><path d="M${xy(innerStart)}L${xy(outerStart)}" stroke="#16334c" stroke-width="3"/>${tangent?`<path d="M65 ${fmt(outerStart[1])}H${fmt(outerStart[0])}M65 ${fmt(innerStart[1])}H${fmt(innerStart[0])}M65 ${fmt(outerStart[1])}V${fmt(innerStart[1])}" stroke="#1675ad" stroke-width="3"/>`:''}<circle cx="565" cy="151" r="59" stroke="#16334c" stroke-width="3"/><path d="M${circle[0]-cr} ${circle[1]}h${cr*2}M${circle[0]} ${circle[1]-cr}v${cr*2}" stroke="#8da5ba" stroke-dasharray="3 3"/></g><g fill="#1675ad">${marks}</g><g fill="#162c43" font-family="Arial,Microsoft JhengHei" font-size="12"><text x="18" y="278">保留原端口${tangent?` · 端部直段 ${fmt(tangent)} mm`:''}</text><text x="18" y="298">外背沿弧 ${fmt(e.outerArc)} mm · 內腹沿弧 ${fmt(e.innerArc)} mm</text><text x="18" y="316">從保留端面量：上述弧長${tangent?`各加 ${fmt(tangent)} mm`:'（無端部直段）'}</text><text x="${fmt(Math.min(350,outer[0]+12))}" y="${fmt(outer[1]+5)}" fill="#a45d08">成品切面</text><text x="270" y="67" fill="#6e7d8c">灰色切掉</text><text x="484" y="50">從保留端朝彎頭內看</text><text x="565" y="77" text-anchor="middle">0° 外背</text><text x="637" y="149">90° 右</text><text x="565" y="234" text-anchor="middle">180° 內腹</text><text x="492" y="149" text-anchor="end">270° 左</text><text x="449" y="269">周長 π × OD＝${fmt(Math.PI*od)} mm</text><text x="449" y="289">先周向分點，再沿各自母線量弧長</text><text x="449" y="309">分點連成切面；切面為圓，側視為直線</text></g></svg>`;
}
export function elbowCutSteps(e,od){
  if(!e||e.kind!=='cut')return '';
  const side=(e.innerArc+e.outerArc)/2,t=e.tangent??0,measure=v=>fmt(v+t);
  return `<ol class="offset-shop-steps"><li>標「${e.end}／保留端」。保留原端口接既有管口；切短的那端接中間直管。</li><li>在保留端圓周標外背 0°、右 90°、內腹 180°、左 270°；周長 ${fmt(Math.PI*od)} mm，再按分點表分成 ${e.stations.length-1} 份。</li><li>捲尺從保留端沿外表面量：外背 <strong>${measure(e.outerArc)} mm</strong>、內腹 <strong>${measure(e.innerArc)} mm</strong>、左右各 <strong>${measure(side)} mm</strong>。${t?`其中包含保留端直段 ${fmt(t)} mm；下方分點表只列彎曲弧長，從端面量時各加此直段。`:'量尺貼弧面，不能拉直量弦長。'}</li><li>其他分點沿同一周向母線量，不斜跨母線；標點後用可彎曲的尺條平順連成一圈。只有四點時增加核對點，避免徒手連線偏離切面。</li><li>標記廢料側，用砂輪機在廢料側留線切除，再修磨到成品線；坡口、鈍邊按 WPS 製作，切片厚度不從保留尺寸再扣一次。</li><li>核對切口平面與外背／內腹尺寸；和直管試組，量四周根部間隙及內外錯邊，再定位點焊。</li></ol>`;
}
